//autogenerated:yes
//nolint:revive,govet,errcheck
package storm32_test

import (
	"testing"

	dialectpkg "github.com/bluenviron/gomavlib/v4/pkg/dialects/storm32"
	"github.com/stretchr/testify/require"
)

func TestEnum_MLRS_RADIO_LINK_TYPE(t *testing.T) {
	t.Run("zero", func(t *testing.T) {
		var e dialectpkg.MLRS_RADIO_LINK_TYPE
		e.UnmarshalText([]byte{})
		e.MarshalText()
		e.String()
	})

	t.Run("first entry", func(t *testing.T) {
		enc, err := dialectpkg.MLRS_RADIO_LINK_TYPE_GENERIC.MarshalText()
		require.NoError(t, err)

		var dec dialectpkg.MLRS_RADIO_LINK_TYPE
		err = dec.UnmarshalText(enc)
		require.NoError(t, err)

		require.Equal(t, dialectpkg.MLRS_RADIO_LINK_TYPE_GENERIC, dec)
	})
}
